//! moyo audit against spglib golden data (Task 0.3.3).
//!
//! The JSON input is generated by the audit script from the same corpus and
//! records spglib's space group, Hall number, Wyckoff letters, operation count
//! and standardized lattice for four tolerances.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]

use moyo::MoyoDataset;
use moyo::base::{AngleTolerance, Cell, Lattice};
use moyo::data::Setting;
use nalgebra::{Matrix3, Vector3};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Audit {
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    lattice: [[f64; 3]; 3],
    positions: Vec<[f64; 3]>,
    numbers: Vec<i32>,
    results: std::collections::BTreeMap<String, Option<SpglibResult>>,
}

#[derive(Debug, Deserialize)]
struct SpglibResult {
    number: i32,
    hall_number: i32,
    wyckoffs: Vec<String>,
    n_operations: usize,
    std_lattice: [[f64; 3]; 3],
}

fn audit() -> Audit {
    serde_json::from_str(include_str!("../../../tests/golden/moyo-audit.json"))
        .expect("moyo audit JSON must be valid")
}

fn cell(case: &Case) -> Cell {
    let matrix = Matrix3::from_fn(|row, column| case.lattice[row][column]);
    let positions = case
        .positions
        .iter()
        .map(|position| Vector3::new(position[0], position[1], position[2]))
        .collect();
    Cell::new(Lattice::new(matrix), positions, case.numbers.clone())
}

fn parameters(lattice: &Matrix3<f64>) -> ([f64; 3], [f64; 3]) {
    let lengths = [
        lattice.row(0).norm(),
        lattice.row(1).norm(),
        lattice.row(2).norm(),
    ];
    let angles = [
        lattice.row(0).dot(&lattice.row(1)) / (lengths[0] * lengths[1]),
        lattice.row(0).dot(&lattice.row(2)) / (lengths[0] * lengths[2]),
        lattice.row(1).dot(&lattice.row(2)) / (lengths[1] * lengths[2]),
    ]
    .map(f64::acos)
    .map(f64::to_degrees);
    (lengths, angles)
}

#[test]
fn moyo_matches_spglib_on_the_audit_corpus() {
    let audit = audit();
    let mut compared = 0;
    let mut disagreements = Vec::new();

    for case in &audit.cases {
        let input = cell(case);
        for (symprec, expected) in &case.results {
            let Some(expected) = expected else {
                continue;
            };
            let symprec: f64 = symprec.parse().expect("numeric symprec");
            let dataset = match MoyoDataset::new(
                &input,
                symprec,
                AngleTolerance::default(),
                Setting::Spglib,
                true,
            ) {
                Ok(dataset) => dataset,
                Err(error) => {
                    disagreements
                        .push(format!("{} @ {symprec}: moyo failed: {error:?}", case.name));
                    continue;
                }
            };
            compared += 1;
            if dataset.number != expected.number {
                disagreements.push(format!(
                    "{} @ {symprec}: number {} != {}",
                    case.name, dataset.number, expected.number
                ));
            }
            if dataset.hall_number != expected.hall_number {
                disagreements.push(format!(
                    "{} @ {symprec}: hall {} != {}",
                    case.name, dataset.hall_number, expected.hall_number
                ));
            }
            if dataset.operations.len() != expected.n_operations {
                disagreements.push(format!(
                    "{} @ {symprec}: operations {} != {}",
                    case.name,
                    dataset.operations.len(),
                    expected.n_operations
                ));
            }
            let expected_wyckoffs: Vec<char> = expected
                .wyckoffs
                .iter()
                .filter_map(|letter| letter.chars().next())
                .collect();
            // Si is a known origin-choice difference: spglib reports 8a in
            // Hall 525, moyo reports 8b for the same structure. Recorded in
            // docs/algorithms/symmetry-backend.md.
            if case.name != "simple/Si.cif" && dataset.wyckoffs != expected_wyckoffs {
                disagreements.push(format!(
                    "{} @ {symprec}: wyckoffs {:?} != {:?}",
                    case.name, dataset.wyckoffs, expected_wyckoffs
                ));
            }
            if known_std_lattice_exception(&case.name) {
                continue;
            }
            let (lengths, angles) = parameters(&dataset.std_cell.lattice.basis);
            let (expected_lengths, expected_angles) =
                parameters(&Matrix3::from_fn(|row, column| {
                    expected.std_lattice[row][column]
                }));
            for axis in 0..3 {
                if (lengths[axis] - expected_lengths[axis]).abs()
                    > 1e-4 * expected_lengths[axis].max(1.0)
                {
                    disagreements.push(format!(
                        "{} @ {symprec}: std length {axis} {} != {}",
                        case.name, lengths[axis], expected_lengths[axis]
                    ));
                }
                if (angles[axis] - expected_angles[axis]).abs() > 1e-4 {
                    disagreements.push(format!(
                        "{} @ {symprec}: std angle {axis} {} != {}",
                        case.name, angles[axis], expected_angles[axis]
                    ));
                }
            }
        }
    }

    assert!(compared > 0, "the audit data has no comparable case");
    assert!(
        disagreements.is_empty(),
        "moyo/spglib disagreements:\n{}",
        disagreements.join("\n")
    );
}

fn known_std_lattice_exception(name: &str) -> bool {
    matches!(
        name,
        "simple/graphite.cif" | "simple/quartz.cif" | "edge/triclinic.cif" | "edge/hexagonal.cif"
    )
}
